import os
import time
import datetime

from .base import BaseTshark
from .builder import CountingCmdBuilder
from threading import current_thread
from ute_tshark.exception import GettingPacketsNumberIsImpossible, WaitingForPacketTimeout, TsharkExecutionError


class CountingPackets(BaseTshark):
    """ Class handles packets counting on virtual machine.

    :note: SSH protocol was used as a communication protocol.
    """
    def __init__(self, ssh_client, tshark_dir, interface, log_dir='/tmp', snaplen=65555, preferences=None):
        """
        :param ssh_client:              SSHLibrary instance with established connection.
        :param string tshark_dir:       Path to dictionary where tshark is located.
        :param string interface:        Local or remote virtual machine interface which is used to packects capture.
        :param string log_dir:          Directory name where pcap file is stored.
        :param string log_name:         File name where packets are stored.
        :param integer snaplen:         Amount of data for each frame that is captured.
        """
        super(CountingPackets, self).__init__(ssh_client, tshark_dir, interface, log_dir, snaplen, preferences)
        self._tmp_log_path = self._make_temporary_pcap_file_name()

    def start_counting(self, packet_filter):
        """ Start counting packet with given capture filter.

         :param integer packet_filter    Packet filter definition   (equivalent of -Y in tshark).

        """

        cmd = self._build_wait_for_packets_command(packet_filter)
        self.start_process(cmd)

    def stop_counting(self):
        """ Stop counting packets with given capture filter.

        """
        self.stop_process()

    def get_packet_number(self):
        """ Get number of packets collected by start_counting method.

        :return integer:        Amount of captured packets.
        :rtype:                 integer
        """
        try:
            return int(self._execute("grep -c ^ {};:".format(self._tmp_log_path)))
        except TsharkExecutionError as e:
            raise GettingPacketsNumberIsImpossible(str(e))

    def wait_for_packets(self, packets_number, timeout=120):
        """Wait until given packets are captured.

        :param integer packet_number:   Maximum number of packets to be captured.
        :param integer timeout:         Maximum number of seconds to wait for a given number of packets are captured.

        """
        packets_number = int(packets_number)
        timeout = int(timeout)
        captured_packets = 0
        start = time.time()
        while time.time() - start < timeout:
            captured_packets = self.get_packet_number()
            if captured_packets >= packets_number:
                return True
            time.sleep(0.5)
        raise WaitingForPacketTimeout("Waiting for %d packets time expired, %d packets were captured" % (packets_number, captured_packets))

    def _build_wait_for_packets_command(self, packet_filter):
        return CountingCmdBuilder(self._tshark_dir, self._interface, packet_filter, self._tmp_log_path,
                                  self._display_filter, self._preferences, self._log_dir).build()

    def _make_temporary_pcap_file_name(self):
        log_name = '{}_{}.txt'.format(abs(current_thread().ident), datetime.datetime.now().strftime("%y-%m-%d_%H-%M-%S"))
        return os.path.join(self._log_dir, log_name)
